// "Use stock" on the ticked items only (follows Odoo Check Availability): earliest customer date first, free units only, Suggested order.
function autoReserve(sos, ids) {
  const order = []; sos.forEach(s => s.items.forEach(i => order.push({ s, i })));
  order.sort((a, b) => (a.s.cdate || 9e15) - (b.s.cdate || 9e15) || (a.s.proc || 9e15) - (b.s.proc || 9e15));
  const done = new Map();
  order.forEach(({ s, i }) => { if (ids && !ids.has(i.id)) return; const m = matchStock(i); if (!m || m.n < i.qty) return; const units = m.list.slice(0, i.qty); units.forEach(u => TAKEN.add(u.id)); done.set(i, { loc: [...new Set(units.map(u => u.loc))].join(', '), unit: units[0].id, units: units.map(u => u.id), auto: true }); });
  return sos.map(s => ({ ...s, items: s.items.map(i => done.has(i) ? { ...i, res: done.get(i) } : i) }));
}
